// GENERATED by datrix-codegen-flutter. DO NOT EDIT.
//
// What every generated form shares. A form holds its value in its wire form
// -- the JSON its body model decodes, a picked file for a file field -- under
// field paths: dot-separated wire names relative to the body, an array
// element as `[n]` (the one field-error path rule every backend realizes).
// Every validator is derived from the bound struct's fields and every rule
// also runs on the server; the client run is an early copy of the same
// decision. A failed submission binds a `request-validation` problem's field
// errors onto the fields they name (the rest show at the form's level), shows
// a rule-based `validation` problem's message, and shows any other problem as
// its exception's text.

import 'package:flutter/material.dart';
import 'package:datrix_client/api/core/domain_errors.dart';
import 'package:datrix_client/api/core/exceptions.dart';
import 'package:datrix_client/api/core/problem.dart';
import 'package:datrix_client/api/core/transport.dart';
import 'package:datrix_client/core/runtime.dart';

/// The family of a rule-based validation problem, whose detail is the rule's own message.
const String _ruleValidationFamily = 'validation';

/// How a leaf field's input becomes its wire value.
enum DtxFieldKind { text, integer, number, decimalText, boolean, date, time, dateTime, choice, file }

/// The value of a form, by field path, and what its fields show.
class DtxFormModel extends ChangeNotifier {
  Map<String, Object?> _value = {};
  final Map<String, String> _serverErrors = {};

  /// The failure the form shows at its own level, as text.
  String? formError;

  /// A submission is in flight.
  bool submitting = false;

  /// Whether the form holds its starting values. Until it does it is not
  /// shown and cannot be submitted: an edit submitted over values that never
  /// loaded would overwrite the stored ones. A form that starts empty is
  /// loaded from the start.
  bool loaded = true;

  /// Why the starting values could not be loaded, or `null`; the form shows
  /// it with a retry.
  Object? loadFailure;

  /// The starting values are loading.
  void startLoading() {
    loaded = false;
    loadFailure = null;
    notifyListeners();
  }

  /// The starting values have loaded.
  void finishLoading() {
    loaded = true;
    notifyListeners();
  }

  /// Loading the starting values failed with [failure].
  void failLoading(Object failure) {
    loadFailure = failure;
    notifyListeners();
  }

  /// The whole value, as its body model decodes it.
  Map<String, Object?> get wire => _value;

  /// Replaces the whole value (a loaded entity, an edited draft).
  void load(Map<String, Object?> value) {
    _value = _copy(value);
    _serverErrors.clear();
    notifyListeners();
  }

  static Map<String, Object?> _copy(Map<String, Object?> value) => {for (final entry in value.entries) entry.key: _copyValue(entry.value)};

  static Object? _copyValue(Object? value) => switch (value) {
    final Map<String, Object?> map => _copy(map),
    final List<Object?> list => [for (final item in list) _copyValue(item)],
    _ => value,
  };

  static List<Object> _segments(String path) {
    final segments = <Object>[];
    for (final part in path.split('.')) {
      final open = part.indexOf('[');
      if (open < 0) {
        segments.add(part);
        continue;
      }
      segments.add(part.substring(0, open));
      for (final index in RegExp(r'\[(\d+)\]').allMatches(part)) {
        segments.add(int.parse(index.group(1)!));
      }
    }
    return segments;
  }

  /// The value at [path], or `null` when nothing is set there.
  Object? valueAt(String path) {
    Object? current = _value;
    for (final segment in _segments(path)) {
      current = switch ((current, segment)) {
        (final Map<String, Object?> map, final String key) => map[key],
        (final List<Object?> list, final int index) when index < list.length => list[index],
        _ => null,
      };
    }
    return current;
  }

  /// Sets the value at [path], creating the groups on the way.
  void setValue(String path, Object? value) {
    final segments = _segments(path);
    Object? container = _value;
    for (var i = 0; i < segments.length - 1; i++) {
      container = _child(container, segments[i], segments[i + 1] is int);
    }
    final last = segments.last;
    if (container is Map<String, Object?> && last is String) {
      container[last] = value;
    } else if (container is List<Object?> && last is int && last < container.length) {
      container[last] = value;
    } else {
      throw StateError('Form path $path does not name a field of this form.');
    }
    _serverErrors.remove(path);
    notifyListeners();
  }

  static Object? _child(Object? container, Object segment, bool listNext) {
    if (container is Map<String, Object?> && segment is String) {
      return container.putIfAbsent(segment, () => listNext ? <Object?>[] : <String, Object?>{});
    }
    if (container is List<Object?> && segment is int && segment < container.length) {
      return container[segment] ??= listNext ? <Object?>[] : <String, Object?>{};
    }
    throw StateError('A form path passes through a value that is neither a group nor a list.');
  }

  /// The items of the repeatable field at [path].
  List<Object?> itemsAt(String path) {
    final items = valueAt(path);
    return items is List<Object?> ? items : const [];
  }

  /// Appends [item] to the repeatable field at [path].
  void addItem(String path, Object? item) {
    final items = valueAt(path);
    if (items is List<Object?>) {
      items.add(item);
    } else {
      setValue(path, <Object?>[item]);
      return;
    }
    notifyListeners();
  }

  /// Removes the item at [index] of the repeatable field at [path].
  void removeItem(String path, int index) {
    final items = valueAt(path);
    if (items is List<Object?> && index < items.length) {
      items.removeAt(index);
      _serverErrors.removeWhere((key, _) => key.startsWith('$path['));
      notifyListeners();
    }
  }

  /// The server's message for the field at [path], or `null`.
  String? serverErrorAt(String path) => _serverErrors[path];

  /// Binds each field error to the field its path names; returns the ones
  /// naming no field of this form.
  List<FieldError> applyFieldErrors(List<FieldError> errors, Iterable<String> fieldPaths) {
    final unmatched = <FieldError>[];
    for (final error in errors) {
      if (fieldPaths.contains(_patternOf(error.field))) {
        _serverErrors[error.field] = error.message;
      } else {
        unmatched.add(error);
      }
    }
    notifyListeners();
    return unmatched;
  }

  /// A concrete path with every index replaced by `[]`, as the form's field
  /// paths name repeatable elements.
  static String _patternOf(String path) => path.replaceAll(RegExp(r'\[\d+\]'), '[]');

  /// Shows the failed submission [error] -- a request-validation problem's
  /// field errors on their fields, anything else at the form's level. (A
  /// failure that is not a problem answer never reaches here: the form
  /// catches only a `DatrixException`.)
  void showFailure(DatrixException error, Iterable<String> fieldPaths) {
    final problem = error.problem;
    final messages = datrixRuntime.messages;
    if (problem == null) {
      formError = messages.key('framework.failed').text;
    } else if (problem.errors.isNotEmpty) {
      final unmatched = applyFieldErrors(problem.errors, fieldPaths);
      formError = unmatched.isEmpty ? null : unmatched.map((e) => e.message).join(' ');
    } else if (problemFamily(problem) == _ruleValidationFamily) {
      formError = problem.detail.isNotEmpty ? problem.detail : problem.title;
    } else {
      final family = problemFamily(problem);
      formError = messages.key(domainErrorLabelKeysByProblemFamily[family] ?? builtinErrorLabelKeysByProblemFamily[family] ?? 'framework.failed').text;
    }
    notifyListeners();
  }
}

/// A field's validators, derived from its declaration: required, length,
/// and a decimal's digits. Each returns the message to show, or `null`.
class DtxFieldRules {
  const DtxFieldRules({this.required = false, this.minLength, this.maxLength, this.precision, this.scale});

  final bool required;
  final int? minLength;
  final int? maxLength;
  final int? precision;
  final int? scale;

  String? check(Object? value) {
    final messages = datrixRuntime.messages;
    final empty = value == null || (value is String && value.isEmpty);
    if (empty) {
      return required ? messages.key('framework.required').text : null;
    }
    final min = minLength;
    final max = maxLength;
    if (value is String && min != null && value.length < min) {
      return messages.key('framework.tooShort', {'min': min}).text;
    }
    if (value is String && max != null && value.length > max) {
      return messages.key('framework.tooLong', {'max': max}).text;
    }
    final digits = precision;
    if (digits != null && !_fitsDigits('$value', digits, scale)) {
      return messages.key('framework.invalid').text;
    }
    return null;
  }

  static bool _fitsDigits(String text, int precision, int? scale) {
    final places = scale ?? 0;
    final integers = places > 0 ? (precision - places < 1 ? 1 : precision - places) : precision;
    final pattern = places > 0 ? RegExp('^-?\\d{1,$integers}(\\.\\d{1,$places})?\$') : RegExp('^-?\\d{1,$integers}\$');
    return pattern.hasMatch(text);
  }
}

/// A leaf field's text as its wire value, or `null` when the text does not
/// read as one (the field then shows it is invalid).
Object? dtxParseField(DtxFieldKind kind, String text) {
  if (text.isEmpty) {
    return null;
  }
  return switch (kind) {
    DtxFieldKind.integer => int.tryParse(text),
    DtxFieldKind.number => double.tryParse(text),
    DtxFieldKind.decimalText => double.tryParse(text) == null ? null : text,
    _ => text,
  };
}

/// A leaf field's wire value as the text its input shows.
String dtxFieldText(Object? value) => value == null ? '' : '$value';

/// A form: its sections, its form-level failure, and its submit button.
class DtxFormView extends StatelessWidget {
  const DtxFormView({super.key, required this.model, required this.onSubmit, this.onRetry, required this.children});

  final DtxFormModel model;
  final VoidCallback onSubmit;

  /// Loads the starting values again after a failed load.
  final VoidCallback? onRetry;
  final List<Widget> children;

  @override
  Widget build(BuildContext context) {
    final messages = datrixRuntime.messages;
    final failure = model.loadFailure;
    if (failure != null) {
      // The same failure state a data binding shows.
      final problem = failure is DatrixException ? failure.problem : null;
      final title = problem == null ? messages.key('framework.failed').text : problem.title;
      final detail = problem?.detail ?? '';
      return Semantics(
        liveRegion: true,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(title, style: Theme.of(context).textTheme.titleMedium),
            if (detail.isNotEmpty) Text(detail),
            const SizedBox(height: 12),
            FilledButton(onPressed: onRetry, child: Text(messages.key('framework.retry').text)),
          ],
        ),
      );
    }
    if (!model.loaded) {
      return Semantics(
        label: messages.key('framework.loading').text,
        liveRegion: true,
        child: const Center(child: CircularProgressIndicator()),
      );
    }
    final error = model.formError;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        ...children,
        if (error != null)
          Semantics(
            liveRegion: true,
            child: Text(error, style: TextStyle(color: Theme.of(context).colorScheme.error)),
          ),
        Align(
          alignment: AlignmentDirectional.centerStart,
          child: FilledButton(onPressed: model.submitting ? null : onSubmit, child: Text(datrixRuntime.messages.key('framework.submit').text)),
        ),
      ],
    );
  }
}

/// A titled group of fields: a step, or a nested struct's field group.
class DtxFieldSection extends StatelessWidget {
  const DtxFieldSection({super.key, this.title, required this.children});

  final String? title;
  final List<Widget> children;

  @override
  Widget build(BuildContext context) {
    final heading = title;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        if (heading != null) Semantics(header: true, child: Text(heading, style: Theme.of(context).textTheme.titleMedium)),
        ...children,
      ],
    );
  }
}

/// One text-entered field: text, a number, a date, a time or a date-time.
class DtxTextField extends StatefulWidget {
  const DtxTextField({super.key, required this.model, required this.path, required this.label, required this.kind, this.rules = const DtxFieldRules(), this.readOnly = false, this.multiline = false});

  final DtxFormModel model;
  final String path;
  final String label;
  final DtxFieldKind kind;
  final DtxFieldRules rules;
  final bool readOnly;
  final bool multiline;

  @override
  State<DtxTextField> createState() => _DtxTextFieldState();
}

class _DtxTextFieldState extends State<DtxTextField> {
  late final TextEditingController _controller = TextEditingController(text: dtxFieldText(widget.model.valueAt(widget.path)));

  @override
  void didUpdateWidget(covariant DtxTextField oldWidget) {
    super.didUpdateWidget(oldWidget);
    final text = dtxFieldText(widget.model.valueAt(widget.path));
    if (dtxParseField(widget.kind, _controller.text) != widget.model.valueAt(widget.path) && _controller.text != text) {
      _controller.text = text;
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  TextInputType get _keyboard => switch (widget.kind) {
    DtxFieldKind.integer => TextInputType.number,
    DtxFieldKind.number || DtxFieldKind.decimalText => const TextInputType.numberWithOptions(decimal: true, signed: true),
    DtxFieldKind.date || DtxFieldKind.time || DtxFieldKind.dateTime => TextInputType.datetime,
    _ => widget.multiline ? TextInputType.multiline : TextInputType.text,
  };

  String? _validate(String? text) {
    final entered = text ?? '';
    final value = dtxParseField(widget.kind, entered);
    if (entered.isNotEmpty && value == null) {
      return datrixRuntime.messages.key('framework.invalid').text;
    }
    return widget.rules.check(value);
  }

  @override
  Widget build(BuildContext context) {
    return TextFormField(
      controller: _controller,
      readOnly: widget.readOnly,
      keyboardType: _keyboard,
      minLines: widget.multiline ? 3 : 1,
      maxLines: widget.multiline ? null : 1,
      decoration: InputDecoration(labelText: widget.label, errorText: widget.model.serverErrorAt(widget.path)),
      validator: _validate,
      onChanged: (text) => widget.model.setValue(widget.path, dtxParseField(widget.kind, text)),
    );
  }
}

/// A choice among an enum's members, by wire value.
class DtxChoiceField extends StatelessWidget {
  const DtxChoiceField({super.key, required this.model, required this.path, required this.label, required this.options, this.rules = const DtxFieldRules(), this.readOnly = false});

  final DtxFormModel model;
  final String path;
  final String label;

  /// `wire value -> label`.
  final Map<String, String> options;
  final DtxFieldRules rules;
  final bool readOnly;

  @override
  Widget build(BuildContext context) {
    final current = model.valueAt(path);
    return DropdownButtonFormField<String>(
      initialValue: current is String && options.containsKey(current) ? current : null,
      decoration: InputDecoration(labelText: label, errorText: model.serverErrorAt(path)),
      items: [for (final entry in options.entries) DropdownMenuItem(value: entry.key, child: Text(entry.value))],
      validator: rules.check,
      onChanged: readOnly ? null : (value) => model.setValue(path, value),
    );
  }
}

/// A yes/no field.
class DtxToggleField extends StatelessWidget {
  const DtxToggleField({super.key, required this.model, required this.path, required this.label, this.readOnly = false});

  final DtxFormModel model;
  final String path;
  final String label;
  final bool readOnly;

  @override
  Widget build(BuildContext context) {
    final error = model.serverErrorAt(path);
    return SwitchListTile(
      title: Text(label),
      subtitle: error == null ? null : Text(error, style: TextStyle(color: Theme.of(context).colorScheme.error)),
      value: model.valueAt(path) == true,
      onChanged: readOnly ? null : (value) => model.setValue(path, value),
    );
  }
}

/// A file chosen from the device, sent as a multipart part.
class DtxFileField extends StatelessWidget {
  const DtxFileField({super.key, required this.model, required this.path, required this.label, this.rules = const DtxFieldRules(), this.readOnly = false});

  final DtxFormModel model;
  final String path;
  final String label;
  final DtxFieldRules rules;
  final bool readOnly;

  Future<void> _choose() async {
    final file = await datrixRuntime.media.pickFile(null);
    if (file != null) {
      model.setValue(path, file);
    }
  }

  @override
  Widget build(BuildContext context) {
    final chosen = model.valueAt(path);
    return FormField<Object?>(
      initialValue: chosen,
      validator: (_) => rules.check(model.valueAt(path)),
      builder: (state) => InputDecorator(
        decoration: InputDecoration(labelText: label, errorText: state.errorText ?? model.serverErrorAt(path)),
        child: Row(
          children: [
            Expanded(child: Text(chosen is UploadFile ? chosen.filename : '')),
            TextButton(onPressed: readOnly ? null : _choose, child: Text(datrixRuntime.messages.key('framework.add').text)),
          ],
        ),
      ),
    );
  }
}

/// A repeatable field: its items, each with a remove action, and an add action.
class DtxRepeatable extends StatelessWidget {
  const DtxRepeatable({super.key, required this.model, required this.path, required this.label, required this.item, required this.create});

  final DtxFormModel model;
  final String path;
  final String label;

  /// The widgets of the item at an index.
  final List<Widget> Function(int index) item;

  /// A new item's empty value.
  final Object? Function() create;

  @override
  Widget build(BuildContext context) {
    final messages = datrixRuntime.messages;
    final count = model.itemsAt(path).length;
    return DtxFieldSection(
      title: label,
      children: [
        for (var index = 0; index < count; index++) ...[
          ...item(index),
          Align(
            alignment: AlignmentDirectional.centerEnd,
            child: TextButton(onPressed: () => model.removeItem(path, index), child: Text(messages.key('framework.remove').text)),
          ),
        ],
        Align(
          alignment: AlignmentDirectional.centerStart,
          child: TextButton(onPressed: () => model.addItem(path, create()), child: Text(messages.key('framework.add').text)),
        ),
      ],
    );
  }
}
